    }

    /// Contract v7: a failed BLOCK_COMPLETE — the resume grant (Granted,
    /// or Active on this lane) → Failed; the partial stays unstamped.
    async fn fail_resume_record(&self, relative_path: &str, reason: &str) -> Result<SinkOutcome> {
        self.require_resume()?;
        self.ledger()
